import { stdout } from std.io;
class Pair<A, B> {
    a: A;
    b: B;
    construct(a: A, b: B) { this.a = a; this.b = b; }
    first(): A { return this.a; }
    second(): B { return this.b; }
}
class Box<T> {
    item: T;
    construct(item: T) { this.item = item; }
    get(): T { return this.item; }
}
fn main(): Void {
    mut p: Pair<String, Int32> = Pair("k", 2);
    stdout.println(p.first());
    stdout.println(p.second());
    mut q: Pair<Int32, Int32> = Pair(1, 2);
    stdout.println(q.first() + q.second());
    mut bi: Box<Int32> = Box(5);
    mut bs: Box<String> = Box("s");
    stdout.println(bi.get());
    stdout.println(bs.get());
}
